export const ALL_HENTAI = [...HENTAI_VOST, ...HENTAI_BAZA];
export const ALL_ANIME = SFW_ANIME;

// ─── CamelCase mapper for frontend compatibility ───────────────
function toCamel(obj: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    const camel = k.replace(/_([a-z])/g, (_, c) => c.toUpperCase());
    if (Array.isArray(v) && v.length > 0 && typeof v[0] === 'object' && v[0] !== null) {
      out[camel] = (v as Record<string, unknown>[]).map(toCamel);
    } else {
      out[camel] = v;
    }
  }
  return out;
}

export function mapToCamel<T>(items: T[]): T[] {
  return items.map(i => toCamel(i as Record<string, unknown>)) as T[];
}

// favorites & history moved to Supabase DB — these stubs kept for backward compat
const _favoritesStore = new Set<string>();
const _historyStore = new Map<string, { episodeNumber: number; watchedAt: string }>();
export function getFavorites(): string[] { return [..._favoritesStore]; }
export function addFavorite(id: string) { _favoritesStore.add(id); }
export function removeFavorite(id: string) { _favoritesStore.delete(id); }
export function getHistory() { return [..._historyStore.entries()].map(([animeId, v]) => ({ animeId, ...v })); }
export function upsertHistory(animeId: string, episodeNumber: number) { _historyStore.set(animeId, { episodeNumber, watchedAt: new Date().toISOString() }); }
export const ALL_ANIME_LIST = [...ALL_ANIME, ...ALL_HENTAI];
export function findAnimeById(id: string) { return ALL_ANIME_LIST.find(a => a.id === id); }